-- Create transport_rates table
create table if not exists public.transport_rates (
  id bigint generated by default as identity primary key,
  sheet_name text not null,
  category text not null,
  section_header text,
  route_raw text not null,
  from_location text not null,
  to_location text not null,
  prices jsonb not null default '{}'::jsonb,
  tipping text,
  notes text,
  created_at timestamp with time zone default timezone('utc'::text, now()) not null
);

-- Enable Row Level Security (RLS)
alter table public.transport_rates enable row level security;

-- Drop existing policy if any, then create public read policy
drop policy if exists "Allow public select access" on public.transport_rates;
create policy "Allow public select access" on public.transport_rates for select using (true);

